(() => {
  'use strict';
  const arrow='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6"/></svg>';
  const check='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>';
  const chapters=[
    {label:'1978',title:'Город готовился к большой встрече',text:'18 декабря 1978 года открылся московский комбинат. Его строили накануне Олимпиады-80: городу предстояло встречать гостей со всего мира.',tip:'Всё началось задолго до нашей с тобой смены. Давай запустим эту историю — включи завод.'},
    {label:'Рецепты',title:'За вкусом — в настоящую экспедицию',text:'Сотрудники собирали рецепты кваса в российских деревнях. Этот опыт помог создать «Очаковский», а позже — белый квас «Семейный секрет».',tip:'В основе традиционного кваса — двойное брожение. Выбери обе культуры, и увидишь, как они работают вместе.'},
    {label:'Бренды',title:'Знакомые вкусы. Одна компания.',text:'Сегодня в портфеле «Очаково» есть квас и газированные напитки. У них разные рецептуры и технологии, а качество — общее дело большой команды.',tip:'Ты уже встретил два квасных бренда в предыдущей главе. Попробуй найти их среди бутылок.'},
    {label:'Твоя смена',title:'Следующая глава — твоя',text:'Лаборатория проверяет качество. Операторы следят за линией. Инженеры — за надёжностью, склад — за точностью заказа. На практике рядом будет наставник.',tip:'Какую задачу хочется попробовать первой? Выбирай по интересу. Это знакомство, а не тест на профпригодность.'}
  ];
  const brands=[{id:'cola',name:'CoolCola',kind:'Газированный напиток'},{id:'kvass',name:'Очаковский',kind:'Квас'},{id:'fancy',name:'Fancy',kind:'Газированный напиток'},{id:'secret',name:'Семейный секрет',kind:'Квас'},{id:'street',name:'Street',kind:'Газированный напиток'},{id:'toness',name:'Toness',kind:'Тоник'}];
  const professions=[{id:'lab',title:'Лаборатория',task:'Провести анализ пробы',path:'M8 3h8M10 3v7l-5 9a1.4 1.4 0 0 0 1.2 2h11.6a1.4 1.4 0 0 0 1.2-2l-5-9V3M8 15h8'},{id:'line',title:'Линия розлива',task:'Замечать то, что важно',path:'M7 3h4v5l2 3v10H5V11l2-3ZM17 8h4v13h-4M5 14h8M3 23h20'},{id:'engineering',title:'Инженерный участок',task:'Разобраться в работе датчика',path:'M4 4h16v16H4ZM8 8h8M8 12h3m-3 4h8M16 11v2'},{id:'warehouse',title:'Склад',task:'Собрать точный заказ',path:'m3 7 9-4 9 4v11l-9 4-9-4ZM3 7l9 4 9-4M12 11v11m-4-17 9 4'}];
  const icon = path=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linejoin="round" aria-hidden="true"><path d="${path}"/></svg>`;
  function bottle(brand,index) {
    return `<button class="story-brand" type="button" data-story="brand" data-value="${brand.id}" aria-pressed="false" aria-label="${brand.name}"><span class="story-bottle ${index===1||index===3?'is-kvass':''}" aria-hidden="true"><span class="story-bottle-cap"></span><span class="story-bottle-neck"></span><span class="story-bottle-body"><span class="story-liquid"></span><span class="story-bottle-label">${brand.name}</span><i></i></span></span><strong>${brand.name}</strong><span class="story-brand-kind">Нажми, чтобы выбрать</span></button>`;
  }
  function mount(container,onComplete) {
    let current=0,unlocked=0,done=false,cleaned=false,selectedRole='lab';
    const completed=[false,false,false,false],cultures=new Set(),chosen=new Set(),discoveries=new Set();
    let powered=false,fermentProgress=0;
    const factoryFacts=[{id:'start',label:'Начало пути',x:53,y:38,text:'18 декабря 1978 года открылся московский комбинат «Очаково». Это начало истории предприятия.'},{id:'city',label:'Большая задача',x:78,y:66,text:'Комбинат строили накануне Олимпиады-80: Москва готовилась встречать гостей со всего мира.'},{id:'team',label:'Одна команда',x:48,y:78,text:'За напитком стоит команда: производство, лаборатория, инженеры и склад. На следующих участках ты попробуешь их рабочие задачи.'}];
    let context=null;
    const animations=new Set();
    const root=document.createElement('section');root.className='history-experience';root.setAttribute('aria-label','История Очаково в четырёх главах');container.replaceChildren(root);
    const motion=()=>window.GameMotion?.enabled()!==false;
    const coach=(mood,text)=>window.GameMotion?.coach({mood,text});
    const animate=(targets,from,to)=>{if(!window.gsap||!motion())return;const tween=gsap.fromTo(targets,from,to);animations.add(tween);return tween;};
    function disposeAnimations(){if(context){context.revert();context=null;}animations.forEach(t=>t.kill());animations.clear();}
    function sceneMarkup(){
      if(current===0)return `<div class="story-scene story-scene--factory ${powered?'is-powered':''}"><img class="story-visual-art factory-history-art" src="assets/history-factory.png" alt="Игровая иллюстрация заводских корпусов конца 1970-х" width="1536" height="1024"><div class="story-year"><span>18 декабря</span><strong>1978</strong><small>Открытие комбината</small></div><div class="story-power-line" aria-hidden="true"><span></span><i></i><i></i><i></i></div><span class="story-shutter" aria-hidden="true"></span><button type="button" class="story-scene-action" data-story="power" ${powered?'disabled':''}>${powered?check+' Завод включён':'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="M12 2v10m-5-7a8 8 0 1 0 10 0"/></svg> Включить завод'}</button>${powered?`<div class="factory-story-points">${factoryFacts.map(f=>`<button type="button" data-story="factory-point" data-value="${f.id}" style="--x:${f.x}%;--y:${f.y}%" class="${discoveries.has(f.id)?'is-read':''}" aria-pressed="${discoveries.has(f.id)}"><span>${discoveries.has(f.id)?check:'+'}</span>${f.label}</button>`).join('')}</div>`:''}<span class="story-art-note">Иллюстрированный рассказ</span></div>`;
      if(current===1)return `<div class="story-scene story-scene--recipes ${completed[1]?'is-fermenting':''}"><img class="story-visual-art recipe-history-art" src="assets/history-recipes.png" alt="Полевая записная книжка, зерно и традиционная посуда — иллюстрация сбора рецептов" width="1536" height="1024"><div class="recipe-story-word"><span>Сохранить</span><strong>традицию</strong><small>и понять, как она работает</small></div><div class="story-ferment" aria-hidden="true"><svg viewBox="0 0 180 220" fill="none"><path d="M58 19h64v25l18 20v123c0 16-100 16-100 0V64l18-20Z" fill="#fff" stroke="#ae9d8b" stroke-width="2"/><path d="M44 98h92v87c0 12-92 12-92 0Z" fill="#e3a93d" opacity=".65"/><path d="M60 19h60M47 66h86M90 4v15" stroke="#ae9d8b" stroke-width="3"/><path d="M49 79v99" stroke="white" stroke-width="4"/></svg><div class="ferment-bubbles">${Array.from({length:8},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div><span>Двойное брожение</span></div><div class="story-cultures" role="group" aria-label="Две культуры для кваса"><button type="button" data-story="culture" data-value="yeast" class="${cultures.has('yeast')?'is-selected':''}" aria-pressed="${cultures.has('yeast')}"><span class="culture-dot culture-dot--yeast"></span>Дрожжи ${cultures.has('yeast')?check:'+'}</button><button type="button" data-story="culture" data-value="bacteria" class="${cultures.has('bacteria')?'is-selected':''}" aria-pressed="${cultures.has('bacteria')}"><span class="culture-dot culture-dot--bacteria"></span>Молочнокислые бактерии ${cultures.has('bacteria')?check:'+'}</button></div><span class="story-art-note">Упрощённая модель для знакомства</span></div>`;
      if(current===2)return `<div class="story-scene story-scene--brands"><div class="story-brand-title"><span>От рецепта — к напитку</span><strong>Найди два квасных бренда</strong></div><div class="story-bottles" role="group" aria-label="Выбор двух квасных брендов">${brands.map(bottle).join('')}</div><div class="story-brands-belt" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div></div>`;
      return `<div class="story-scene story-scene--team"><img class="story-team-map" src="assets/factory-map.png" alt="Те самые участки завода, на которых работают разные команды" width="1536" height="1024"><div class="story-team-heading"><strong>Ты уже внутри</strong><span>Выбери первую рабочую задачу</span></div><div class="story-profession-choices">${professions.map(p=>`<button type="button" class="story-profession ${selectedRole===p.id?'is-selected':''}" data-story="role" data-value="${p.id}" aria-pressed="${selectedRole===p.id}">${icon(p.path)}<span><strong>${p.title}</strong><small>${p.task}</small></span><span class="story-choice-mark">${selectedRole===p.id?check:arrow}</span></button>`).join('')}</div></div>`;
    }
    function render(transition=true){
      disposeAnimations();const c=chapters[current];
      root.innerHTML=`<nav class="story-chapters" aria-label="Главы истории">${chapters.map((chapter,i)=>`<button type="button" data-story="chapter" data-value="${i}" class="${i===current?'is-current':''} ${completed[i]?'is-read':''}" ${i>unlocked?'disabled':''} ${i===current?'aria-current="step"':''}><span>${i+1}</span>${chapter.label}</button>`).join('')}</nav>${sceneMarkup()}<div class="story-narrative"><div class="story-narrative-copy"><h1 tabindex="-1">${c.title}</h1><p>${c.text}</p></div>${current===1&&cultures.size===2?`<div class="ferment-scrubber"><label for="ferment-progress">Проведи процесс от начала до контроля <output id="ferment-stage">${fermentProgress<30?'Начало':fermentProgress<70?'Вкус и аромат':'Контроль результата'}</output></label><input id="ferment-progress" type="range" min="0" max="100" step="1" value="${fermentProgress}" aria-label="Ход учебного брожения"><p>Время сжато для знакомства с процессом.</p></div>`:''}<div class="story-status" role="status" aria-live="polite">${statusText()}</div><div class="story-controls"><button type="button" class="text-button story-back" data-story="back" ${current===0?'disabled':''}>Назад</button>${current===2&&!completed[2]?`<button type="button" class="primary" data-story="check-brands" ${chosen.size!==2?'disabled':''}>Проверить выбор ${arrow}</button>`:`<button type="button" class="primary" data-story="next" ${current<3&&!completed[current]?'disabled':''}>${current===3?'Начать с '+({lab:'лаборатории',line:'линии розлива',engineering:'инженерного участка',warehouse:'склада'}[selectedRole]):'Следующая глава'} ${arrow}</button>`}</div><a class="story-source" href="https://ochakovo.ru/istoriya/" target="_blank" rel="noopener">Факты — из истории «Очаково» ↗</a></div>`;
      if(current===2){root.querySelectorAll('.story-brand').forEach(button=>{const selected=chosen.has(button.dataset.value);button.classList.toggle('is-selected',selected);button.setAttribute('aria-pressed',String(selected));if(completed[2]){button.disabled=true;button.querySelector('.story-brand-kind').textContent=brands.find(b=>b.id===button.dataset.value).kind;}});}
      if(window.gsap&&motion()&&transition){context=gsap.context(()=>{gsap.fromTo(root.querySelector('.story-scene'),{opacity:.6},{opacity:1,duration:.45,ease:'power2.out'});gsap.fromTo(root.querySelectorAll('.story-narrative-copy > *'),{y:12,opacity:.4},{y:0,opacity:1,duration:.4,stagger:.07,ease:'power3.out',clearProps:'transform,opacity'});if(current===2)gsap.fromTo(root.querySelectorAll('.story-brand'),{y:25,opacity:.3},{y:0,opacity:1,duration:.5,stagger:.06,ease:'power2.out',clearProps:'transform,opacity'});},root);}
      coach('welcome',c.tip);
    }
    function statusText(){
      if(current===0)return completed[0]?'Все три открытия собраны. Перейдём от завода к его рецептам.':powered?`Исследуй три точки на заводе. Открыто ${discoveries.size} из 3.`:'Нажми «Включить завод», чтобы начать историю.';
      if(current===1)return completed[1]?'После брожения результат проверяет команда качества. Ты проведёшь такой контроль в лаборатории.':cultures.size===2?'Передвинь ползунок: от начала процесса до контроля результата.':cultures.size?'Одна культура уже в деле. Добавь вторую.':'Добавь две культуры и посмотри, что происходит в танке.';
      if(current===2)return completed[2]?'Верно: «Очаковский» и «Семейный секрет» — квас. Остальные здесь — газированные напитки и тоник.':`Выбрано ${chosen.size} из 2. Вспомни предыдущую главу.`;
      return 'Для практики и трудоустройства — 18+. А исследовать можно уже сейчас.';
    }
    function updateStatus(text){const node=root.querySelector('.story-status');if(node)node.textContent=text||statusText();}
    function enableNext(){const button=root.querySelector('[data-story="next"]');if(button)button.disabled=false;}
    function revealPower(){
      if(powered)return;powered=true;render(false);
      root.querySelector('.story-scene').classList.add('is-powered');
      const button=root.querySelector('[data-story="power"]');button.disabled=true;button.innerHTML=check+' Завод включён';updateStatus();
      if(window.gsap&&motion()) {const shutter=root.querySelector('.story-shutter');const tl=gsap.timeline();tl.fromTo(shutter,{scaleX:0,transformOrigin:'left center'},{scaleX:1,duration:.3,ease:'power2.in'}).to(shutter,{scaleX:0,transformOrigin:'right center',duration:.38,ease:'power3.out'}).fromTo(root.querySelector('.factory-history-art'),{scale:.98},{scale:1,duration:.6,ease:'power2.out'},.25);animations.add(tl);}
      coach('success','Вот он — 1978 год. Завод открыт. Теперь узнаем, как старинные рецепты стали частью современного производства.');
    }
    function addCulture(id,target){
      if(cultures.has(id))return;cultures.add(id);target.classList.add('is-selected');target.setAttribute('aria-pressed','true');
      target.innerHTML=`<span class="culture-dot ${id==='yeast'?'culture-dot--yeast':'culture-dot--bacteria'}"></span>${id==='yeast'?'Дрожжи':'Молочнокислые бактерии'} ${check}`;
      if(cultures.size===2){render(false);root.querySelector('.story-scene').classList.add('is-fermenting');coach('success','Две культуры работают вместе. Теперь проведи учебное время процесса ползунком — до контроля результата.');}
      else coach('think','Отлично, первая культура есть. Для двойного брожения нужна ещё одна.');
      updateStatus();animate(root.querySelector(`[data-story="culture"][data-value="${id}"]`),{scale:.97},{scale:1,duration:.25,ease:'power2.out'});
    }
    function chooseBrand(id,target){
      if(completed[2])return;if(chosen.has(id))chosen.delete(id);else if(chosen.size<2)chosen.add(id);else {coach('think','Выбрано уже два. Нажми на выбранную бутылку, чтобы заменить её.');return;}
      target.classList.toggle('is-selected',chosen.has(id));target.setAttribute('aria-pressed',String(chosen.has(id)));
      root.querySelector('[data-story="check-brands"]').disabled=chosen.size!==2;updateStatus();
      animate(target.querySelector('.story-bottle'),{rotation:chosen.has(id)?-3:2},{rotation:0,duration:.35,ease:'power2.out'});
    }
    function checkBrands(){
      if(chosen.has('kvass')&&chosen.has('secret')){completed[2]=true;render(false);coach('success','Точно! «Очаковский» и «Семейный секрет» — квас. Теперь познакомимся с людьми, которые делают напитки.');if(window.gsap&&motion())animate(root.querySelectorAll('.story-brand.is-selected'),{y:-10},{y:0,duration:.5,ease:'power2.out',stagger:.1});}
      else {updateStatus('Пока не та пара. Вспомни, какие названия были в главе про экспедиции. Можно выбрать снова — без штрафа.');coach('think','Подсказка: квасные бренды встретились нам в истории о старинных рецептах.');}
    }
    function click(event){
      const target=event.target.closest('[data-story]');if(!target||!root.contains(target)||target.disabled||cleaned||done)return;
      const type=target.dataset.story;
      if(type==='factory-point'){const f=factoryFacts.find(f=>f.id===target.dataset.value);if(!f)return;discoveries.add(f.id);if(discoveries.size===3)completed[0]=true;target.classList.add('is-read');target.setAttribute('aria-pressed','true');target.querySelector('span').innerHTML=check;updateStatus(f.text+(completed[0]?' Все открытия собраны.':''));if(completed[0])enableNext();coach('welcome',f.text);animate(root.querySelector('.factory-history-art'),{scale:1.025,transformOrigin:`${f.x}% ${f.y}%`},{scale:1,duration:1.2,ease:'power3.out',clearProps:'transform,transformOrigin'});}else if(type==='power')revealPower();else if(type==='culture')addCulture(target.dataset.value,target);else if(type==='brand')chooseBrand(target.dataset.value,target);else if(type==='check-brands')checkBrands();
      else if(type==='role'){selectedRole=target.dataset.value;root.querySelectorAll('.story-profession').forEach(b=>{const on=b.dataset.value===selectedRole;b.classList.toggle('is-selected',on);b.setAttribute('aria-pressed',String(on));b.querySelector('.story-choice-mark').innerHTML=on?check:arrow;});root.querySelector('[data-story="next"]').innerHTML='Начать с '+({lab:'лаборатории',line:'линии розлива',engineering:'инженерного участка',warehouse:'склада'}[selectedRole])+' '+arrow;coach('welcome',({lab:'В лаборатории начнём с пробы: запустим анализ и проверим результат.',line:'На линии посмотрим, как движется партия, и заметим дефекты.',engineering:'Разберём связь датчика и оборудования. Начнём с безопасности.',warehouse:'На складе выберем коробки и соберём заказ по накладной.'}[selectedRole]));}
      else if(type==='back'||type==='chapter'){current=type==='back'?Math.max(0,current-1):Number(target.dataset.value);render();root.querySelector('h1').focus({preventScroll:true});root.scrollIntoView({block:'start',behavior:'instant'});}
      else if(type==='next'){if(current<3){current++;unlocked=Math.max(unlocked,current);render();root.querySelector('h1').focus({preventScroll:true});root.scrollIntoView({block:'start',behavior:'instant'});}else{done=true;completed[3]=true;onComplete?.({id:'intro',score:100,role:'Команда Очаково',learned:'Прошёл историю от открытия завода в 1978 году до знакомых брендов и выбрал первую рабочую задачу.',nextId:selectedRole});}}
    }
    function motionChanged(event){if(event.detail.enabled)return;animations.forEach(t=>{t.progress(1);t.kill();});animations.clear();if(context){context.revert();context=null;}}
    function scrub(event){if(event.target.id!=='ferment-progress')return;fermentProgress=Number(event.target.value);const stage=fermentProgress<30?'Начало':fermentProgress<70?'Вкус и аромат':'Контроль результата';root.querySelector('#ferment-stage').textContent=stage;root.querySelector('.story-ferment').style.setProperty('--ferment',fermentProgress/100);const liquid=root.querySelector('.story-ferment path[fill="#e3a93d"]');liquid.style.transformOrigin='50% 100%';liquid.style.transform=`scaleY(${.3+.7*fermentProgress/100})`;updateStatus(fermentProgress<30?'Культуры добавлены. Процесс начинается.':fermentProgress<70?'Формируются характерные вкус и аромат кваса.':'Дальше — проверка результата: в дело вступает лаборатория.');if(fermentProgress>=90){completed[1]=true;enableNext();coach('success','Процесс изучен. Даже знакомый вкус требует совместной работы производства и лаборатории.');}}
    root.addEventListener('input',scrub);root.addEventListener('click',click);document.addEventListener('ochakovo:motion',motionChanged);render();
    return ()=>{cleaned=true;root.removeEventListener('input',scrub);root.removeEventListener('click',click);document.removeEventListener('ochakovo:motion',motionChanged);disposeAnimations();};
  }
  window.GameStory={mount};
})();
